using System; using System.Windows; using System.Windows.Input; using System.Windows.Interop; using System.Windows.Forms; namespace Saeed.Windows; public partial class MainWindow : Window { const int MarginFromWorkArea=18; public MainWindow(){InitializeComponent();Loaded+=MainWindow_Loaded;LocationChanged+=(_,_)=>KeepOnScreen();SizeChanged+=(_,_)=>KeepOnScreen();} private async void MainWindow_Loaded(object sender,RoutedEventArgs e){await AvatarView.EnsureCoreWebView2Async(); AvatarView.NavigateToString("<html><body style='margin:0;background:#081018;color:white;font-family:Segoe UI;text-align:center;padding-top:240px'>Saeed AI<br><small>C# / WPF Desktop</small></body></html>"); PlaceBottomRight();} private Screen CurrentScreen(){return Screen.FromHandle(new WindowInteropHelper(this).Handle);} private void PlaceBottomRight(){var a=CurrentScreen().WorkingArea;Left=a.Right-ActualWidth-MarginFromWorkArea;Top=a.Bottom-ActualHeight-MarginFromWorkArea;} private void KeepOnScreen(){if(!IsLoaded)return;var a=CurrentScreen().WorkingArea;Left=Math.Max(a.Left,Math.Min(Left,a.Right-ActualWidth));Top=Math.Max(a.Top,Math.Min(Top,a.Bottom-ActualHeight));} protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e){base.OnMouseLeftButtonDown(e);if(e.ButtonState==MouseButtonState.Pressed)DragMove();} private void ChatButton_Click(object sender,RoutedEventArgs e){StatusText.Text="المحادثة قيد البناء";}}